// Récupérer les données de l'email
const items = $input.all();

return items.map(item => {
  const email = item.json;

  // Fonction helper pour extraire un header spécifique
  const getHeader = (headerName) => {
    if (!email.headers || !email.headers[headerName.toLowerCase().replace(/-/g, '-')]) {
      return '';
    }

    // Les headers sont sous forme "Header-Name: valeur"
    const headerValue = email.headers[headerName.toLowerCase().replace(/-/g, '-')];

    // Enlever le préfixe "Header-Name: " si présent
    if (typeof headerValue === 'string') {
      const parts = headerValue.split(': ');
      return parts.length > 1 ? parts.slice(1).join(': ') : headerValue;
    }

    return headerValue || '';
  };

  // Extraire le body text (en priorité le texte brut)
  const getEmailBody = () => {
    // D'abord essayer le champ text
    if (email.text && email.text.trim().length > 0) {
      return email.text.trim();
    }

    // Sinon, essayer de nettoyer le HTML
    if (email.html) {
      // Supprimer les balises HTML basiques pour avoir un aperçu
      return email.html
        .replace(/<style[^>]*>.*?<\/style>/gis, '')
        .replace(/<script[^>]*>.*?<\/script>/gis, '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .substring(0, 1000); // Limiter à 1000 caractères pour l'aperçu
    }

    return '';
  };

  return {
    json: {
      messageId: email.id || '',
      threadId: email.threadId || '',
      from: getHeader('from'),
      to: getHeader('to'),
      subject: getHeader('subject'),
      date: getHeader('date'),
      snippet: email.snippet || '',
      bodyText: email.text || '',
      bodyHtml: email.html || '',
      bodyPreview: getEmailBody(),
      labels: email.labelIds || [],
      sizeEstimate: email.sizeEstimate || 0
    }
  };
});
